16	package retrofit2;
17	
18	import java.util.Objects;
19	import javax.annotation.Nullable;
20	import okhttp3.Headers;
21	import okhttp3.Protocol;
22	import okhttp3.Request;
23	import okhttp3.ResponseBody;
24	
25	/** An HTTP response. */
26	public final class Response<T> {
27	  /** Create a synthetic successful response with {@code body} as the deserialized body. */
28	  public static <T> Response<T> success(@Nullable T body) {
29	    return success(
30	        body,
31	        new okhttp3.Response.Builder() //
32	            .code(200)
33	            .message("OK")
34	            .protocol(Protocol.HTTP_1_1)
35	            .request(new Request.Builder().url("http://localhost/").build())
36	            .build());
37	  }
38	
39	  /**
40	   * Create a synthetic successful response with an HTTP status code of {@code code} and {@code
41	   * body} as the deserialized body.
42	   */
43	  public static <T> Response<T> success(int code, @Nullable T body) {
44	    if (code < 200 || code >= 300) {
45	      throw new IllegalArgumentException("code < 200 or >= 300: " + code);
46	    }
47	    return success(
48	        body,
49	        new okhttp3.Response.Builder() //
50	            .code(code)
51	            .message("Response.success()")
52	            .protocol(Protocol.HTTP_1_1)
53	            .request(new Request.Builder().url("http://localhost/").build())
54	            .build());
55	  }
56	
57	  /**
58	   * Create a synthetic successful response using {@code headers} with {@code body} as the
59	   * deserialized body.
60	   */
61	  public static <T> Response<T> success(@Nullable T body, Headers headers) {
62	    Objects.requireNonNull(headers, "headers == null");
63	    return success(
64	        body,
65	        new okhttp3.Response.Builder() //
66	            .code(200)
67	            .message("OK")
68	            .protocol(Protocol.HTTP_1_1)
69	            .headers(headers)
70	            .request(new Request.Builder().url("http://localhost/").build())
71	            .build());
72	  }
73	
74	  /**
75	   * Create a successful response from {@code rawResponse} with {@code body} as the deserialized
76	   * body.
77	   */
78	  public static <T> Response<T> success(@Nullable T body, okhttp3.Response rawResponse) {
79	    Objects.requireNonNull(rawResponse, "rawResponse == null");
80	    if (!rawResponse.isSuccessful()) {
81	      throw new IllegalArgumentException("rawResponse must be successful response");
82	    }
83	    return new Response<>(rawResponse, body, null);
84	  }
85	
86	  /**
87	   * Create a synthetic error response with an HTTP status code of {@code code} and {@code body} as
88	   * the error body.
89	   */
90	  public static <T> Response<T> error(int code, ResponseBody body) {
91	    Objects.requireNonNull(body, "body == null");
92	    if (code < 400) throw new IllegalArgumentException("code < 400: " + code);
93	    return error(
94	        body,
95	        new okhttp3.Response.Builder() //
96	            .body(new OkHttpCall.NoContentResponseBody(body.contentType(), body.contentLength()))
97	            .code(code)
98	            .message("Response.error()")
99	            .protocol(Protocol.HTTP_1_1)
100	            .request(new Request.Builder().url("http://localhost/").build())
101	            .build());
102	  }
103	
104	  /** Create an error response from {@code rawResponse} with {@code body} as the error body. */
105	  public static <T> Response<T> error(ResponseBody body, okhttp3.Response rawResponse) {
106	    Objects.requireNonNull(body, "body == null");
107	    Objects.requireNonNull(rawResponse, "rawResponse == null");
108	    if (rawResponse.isSuccessful()) {
109	      throw new IllegalArgumentException("rawResponse should not be successful response");
110	    }
111	    return new Response<>(rawResponse, null, body);
112	  }
113	
114	  private final okhttp3.Response rawResponse;
115	  private final @Nullable T body;
116	  private final @Nullable ResponseBody errorBody;
117	
118	  private Response(
119	      okhttp3.Response rawResponse, @Nullable T body, @Nullable ResponseBody errorBody) {
120	    this.rawResponse = rawResponse;
121	    this.body = body;
122	    this.errorBody = errorBody;
123	  }
124	
125	  /** The raw response from the HTTP client. */
126	  public okhttp3.Response raw() {
127	    return rawResponse;
128	  }
129	
130	  /** HTTP status code. */
131	  public int code() {
132	    return rawResponse.code();
133	  }
134	
135	  /** HTTP status message or null if unknown. */
136	  public String message() {
137	    return rawResponse.message();
138	  }
139	
140	  /** HTTP headers. */
141	  public Headers headers() {
142	    return rawResponse.headers();
143	  }
144	
145	  /** Returns true if {@link #code()} is in the range [200..300). */
146	  public boolean isSuccessful() {
147	    return rawResponse.isSuccessful();
148	  }
149	
150	  /** The deserialized response body of a {@linkplain #isSuccessful() successful} response. */
151	  public @Nullable T body() {
152	    return body;
153	  }
154	
155	  /** The raw response body of an {@linkplain #isSuccessful() unsuccessful} response. */
156	  public @Nullable ResponseBody errorBody() {
157	    return errorBody;
158	  }
159	
160	  @Override
161	  public String toString() {
162	    return rawResponse.toString();
163	  }
164	}
